<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import OrderAPI from '@/api/order.api.js'
import { getApiErrorMessage } from '@/api/error'
import { useRestaurantStore } from '@/store/restaurant'
import JalaliDatePicker from '@/components/cost/JalaliDatePicker.vue'
import StatisticsTrend from '@/components/finance/StatisticsTrend.vue'

const restaurant = useRestaurantStore()
const data = ref(null), loading = ref(true), error = ref('')
const filters = reactive({ preset: 'last30', start_date: '', end_date: '', source: '', method: '', status: '' })
const presets = [ ['today','امروز'], ['yesterday','دیروز'], ['last7','۷ روز اخیر'], ['last30','۳۰ روز اخیر'], ['jalali_current','ماه جاری'], ['jalali_previous','ماه قبل'], ['custom','بازه دلخواه'] ]
const sourceLabels = { online: 'سایت', in_store: 'حضوری', phone: 'تلفنی' }
const methodLabels = { pos: 'پوز', cash: 'نقدی', card_to_card: 'کارت‌به‌کارت', wallet: 'کیف پول', online_gateway: 'درگاه آنلاین', other: 'سایر' }
const statusLabels = { pending: 'جدید', prep: 'آماده‌سازی', send: 'در حال ارسال', deliver: 'تحویل‌شده', cancel: 'لغوشده' }
const colors = ['#a9673b', '#4d9b86', '#d7ab67', '#778eb8', '#b67d91', '#8a8b83']
const num = value => Number(value || 0).toLocaleString('fa-IR', { maximumFractionDigits: 0 })
const money = value => value == null ? 'نامشخص' : `${num(value)} تومان`
const date = value => {
  const parsed = new Date(`${String(value).slice(0, 10)}T12:00:00+03:30`)
  return Number.isNaN(parsed.valueOf()) ? '—' : new Intl.DateTimeFormat('fa-IR-u-ca-persian', { timeZone: 'Asia/Tehran', dateStyle: 'medium' }).format(parsed)
}
let requestId = 0
async function load() {
  const version = ++requestId
  if (!restaurant.activeRestaurantId) { loading.value = false; error.value = 'ابتدا رستوران مجاز را انتخاب کنید.'; data.value = null; return }
  if (filters.preset === 'custom' && (!filters.start_date || !filters.end_date)) { loading.value = false; error.value = 'تاریخ آغاز و پایان را انتخاب کنید.'; return }
  loading.value = true; error.value = ''
  try {
    const params = Object.fromEntries(Object.entries(filters).filter(([key, value]) => value && (filters.preset === 'custom' || !['start_date','end_date'].includes(key))))
    const result = await OrderAPI.financialStatistics(restaurant.activeRestaurantId, params)
    if (version === requestId) data.value = result
  } catch (cause) { if (version === requestId) { data.value = null; error.value = getApiErrorMessage(cause) } }
  finally { if (version === requestId) loading.value = false }
}
function choosePreset(value) { filters.preset = value; if (value !== 'custom') load() }
function reset() { Object.assign(filters, { preset: 'last30', start_date: '', end_date: '', source: '', method: '', status: '' }); load() }
watch(() => restaurant.activeRestaurantId, () => { if (restaurant.ready) load() })
onMounted(async () => { await restaurant.initialize(); await load() })
const summary = computed(() => data.value?.summary || {})
const average = computed(() => summary.value.paid_order_count ? summary.value.net_paid_sales / summary.value.paid_order_count : 0)
const maxPayment = computed(() => Math.max(1, ...(data.value?.payments || []).map(row => Number(row.amount))))
const maxProduct = computed(() => Math.max(1, ...(data.value?.online?.top_products || []).map(row => Number(row.quantity))))
const maxHour = computed(() => Math.max(1, ...(data.value?.online?.hours || []).map(row => Number(row.count))))
const maxOnlineOrders = computed(() => Math.max(1, ...(data.value?.online?.order_trend || []).map(row => Number(row.count))))
const sourceTotal = computed(() => (data.value?.sources || []).reduce((sum, row) => sum + Number(row.amount), 0))
const sourceRing = computed(() => {
  if (!sourceTotal.value) return 'var(--surface-subtle)'
  let cursor = 0
  return `conic-gradient(${data.value.sources.map((row, index) => { const start = cursor; cursor += Number(row.amount) / sourceTotal.value * 100; return `${colors[index % colors.length]} ${start}% ${cursor}%` }).join(',')})`
})
</script>

<template>
  <main class="statistics" dir="rtl">
    <header class="hero"><div><span class="eyebrow">نمای مالی حجره <i></i> گزارش زنده</span><h1>آمار مالی و فروش</h1><p>یک نگاه روشن به فروش، وصولی و رفتار سفارش‌های کافه</p></div><button class="refresh" :disabled="loading" @click="load"><span aria-hidden="true">↻</span> به‌روزرسانی</button></header>
    <section class="filter-card" aria-label="فیلترهای آمار">
      <div class="filter-top"><div><strong>بازه گزارش</strong><small v-if="data">{{ date(data.period.start) }} تا {{ date(data.period.end) }} · تهران</small></div><button type="button" class="reset" @click="reset">بازنشانی فیلترها</button></div>
      <div class="presets"><button v-for="[value,label] in presets" :key="value" type="button" :class="{active:filters.preset===value}" @click="choosePreset(value)">{{ label }}</button></div>
      <div class="filters">
        <template v-if="filters.preset==='custom'"><JalaliDatePicker v-model="filters.start_date" placeholder="از تاریخ"/><JalaliDatePicker v-model="filters.end_date" placeholder="تا تاریخ"/></template>
        <label><span>کانال فروش</span><select v-model="filters.source"><option value="">همه کانال‌ها</option><option value="online">سایت</option><option value="in_store">حضوری</option><option value="phone">تلفنی</option></select></label>
        <label><span>روش پرداخت</span><select v-model="filters.method"><option value="">همه روش‌ها</option><option v-for="(label,key) in methodLabels" :key="key" :value="key">{{ label }}</option></select></label>
        <label><span>وضعیت سفارش</span><select v-model="filters.status"><option value="">همه وضعیت‌ها</option><option v-for="(label,key) in statusLabels" :key="key" :value="key">{{ label }}</option></select></label>
        <button class="apply" :disabled="loading" @click="load">اعمال فیلتر</button>
      </div>
    </section>

    <div v-if="loading" class="skeleton-grid" aria-label="در حال دریافت آمار"><div v-for="n in 8" :key="n" class="skeleton"></div></div>
    <div v-else-if="error" class="error-state" role="alert"><strong>دریافت آمار ممکن نشد</strong><span>{{ error }}</span><button @click="load">تلاش مجدد</button></div>
    <template v-else-if="data">
      <section class="kpis" aria-label="شاخص‌های اصلی">
        <article class="kpi primary"><span>فروش خالص پرداخت‌شده</span><strong>{{ money(summary.net_paid_sales) }}</strong><small>{{ num(summary.paid_order_count) }} سفارش پرداخت کامل</small><b>↗</b></article>
        <article class="kpi"><span>وصول موفق ثبت‌شده</span><strong>{{ money(summary.collected) }}</strong><small>بر اساس زمان تأیید پرداخت</small><b>◉</b></article>
        <article class="kpi"><span>مانده پرداخت‌نشده</span><strong>{{ money(summary.outstanding) }}</strong><small>{{ num(summary.unpaid_count) }} سفارش باز در بازه ثبت</small><b>◷</b></article>
        <article class="kpi"><span>سود ناخالص</span><strong class="unavailable">قابل محاسبه نیست</strong><small>کامل بودن هزینه تاریخی مشخص نیست</small><b>◇</b></article>
        <article class="kpi compact"><span>تعداد سفارش‌ها</span><strong>{{ num(summary.order_count) }}</strong><small>سفارش‌های ثبت‌شده</small></article>
        <article class="kpi compact"><span>سفارش‌های لغوشده</span><strong>{{ num(summary.canceled_count) }}</strong><small>{{ summary.order_count ? num(summary.canceled_count / summary.order_count * 100) : '۰' }}٪ از سفارش‌ها</small></article>
        <article class="kpi compact"><span>میانگین سفارش پرداخت‌شده</span><strong>{{ money(average) }}</strong><small>فقط پرداخت کامل و غیرلغوشده</small></article>
        <article class="kpi compact"><span>شارژ کیف پول</span><strong>{{ money(data.wallet.topup_amount) }}</strong><small>شارژ تأییدشده، مستقل از فروش</small></article>
      </section>

      <section class="analytics-grid">
        <article class="panel trend-panel"><header><div><span class="kicker">فروش و جریان دریافت</span><h2>روند فروش و سود</h2><p>فروش بر اساس تاریخ سفارش؛ وصول بر اساس تاریخ تأیید پرداخت</p></div><span class="pill">{{ data.period.grouping==='day' ? 'روزانه' : 'ماهانه' }}</span></header><StatisticsTrend :sales="data.trends.sales" :collections="data.trends.collections" :start="data.period.start" :end="data.period.end" :grouping="data.period.grouping"/><p class="notice">سود نمایش داده نمی‌شود: {{ data.profit.reason }} تصویر هزینه برای {{ num(data.profit.snapshot_items) }} از {{ num(data.profit.paid_items) }} قلم وجود دارد؛ این تعداد به معنی تأیید کامل بودن هزینه نیست.</p></article>
        <article class="panel source-panel"><header><div><span class="kicker">کانال‌های فروش</span><h2>فروش سایت در برابر فروش حضوری</h2><p>بر پایه نوع ثبت سفارش، نه روش تحویل</p></div></header><div class="source-content"><div class="donut" :style="{background:sourceRing}"><div><small>فروش پرداخت‌شده</small><strong>{{ money(sourceTotal) }}</strong></div></div><div class="legend"><div v-for="(row,index) in data.sources" :key="row.order_type"><i :style="{background:colors[index % colors.length]}"></i><span>{{ sourceLabels[row.order_type] || 'نامشخص' }}<small>{{ num(row.count) }} سفارش · میانگین {{ money(Number(row.amount)/row.count) }}</small></span><strong>{{ money(row.amount) }}<small>{{ sourceTotal ? num(Number(row.amount)/sourceTotal*100) : '۰' }}٪</small></strong></div><p v-if="!data.sources.length" class="empty">فروش پرداخت‌شده‌ای وجود ندارد.</p></div></div></article>
        <article class="panel"><header><div><span class="kicker">تفکیک دریافت واقعی</span><h2>فروش بر اساس روش پرداخت</h2><p>پرداخت‌های موفق در بازه تأیید؛ تقسیم پرداخت جداگانه شمرده می‌شود.</p></div></header><div v-if="data.payments.length" class="bar-list"><div v-for="(row,index) in data.payments" :key="row.kind" class="bar-row"><div><span>{{ methodLabels[row.kind] || 'سایر' }}</span><strong>{{ money(row.amount) }}</strong></div><div class="track"><i :style="{width:`${Number(row.amount)/maxPayment*100}%`,background:colors[index % colors.length]}"></i></div></div></div><p v-else class="empty">پرداخت موفقی در این بازه ثبت نشده است.</p><div class="panel-foot"><span>مانده سفارش‌های ثبت‌شده در بازه</span><strong>{{ money(summary.outstanding) }}</strong></div></article>
        <article class="panel"><header><div><span class="kicker">آماده‌سازی و پرداخت</span><h2>وضعیت سفارش‌ها</h2><p>وضعیت تحویل و پرداخت دو شاخص مستقل‌اند.</p></div></header><div class="status-grid"><div v-for="row in data.fulfillment" :key="row.status"><span>{{ statusLabels[row.status] || row.status }}</span><strong>{{ num(row.count) }}</strong></div><p v-if="!data.fulfillment.length" class="empty">سفارشی در این بازه ثبت نشده است.</p></div><div class="panel-foot"><span>پرداخت کامل / پرداخت‌نشده</span><strong>{{ num(summary.paid_order_count) }} / {{ num(summary.unpaid_count) }}</strong></div><div class="panel-foot"><span>ارزش سفارش‌های لغوشده</span><strong>{{ money(summary.canceled_value) }}</strong></div><small class="muted">لغو سفارش به معنی عودت خودکار وجه نیست.</small></article>
      </section>

      <section class="section-heading"><div><span class="eyebrow">کانال آنلاین</span><h2>عملکرد فروش سایت</h2><p>فقط رفتار واقعی سفارش‌ها؛ بدون برآورد بازدید یا نرخ تبدیل</p></div></section>
      <section class="mini-kpis"><article><span>سفارش سایت</span><strong>{{ num(data.online.orders) }}</strong></article><article><span>فروش پرداخت‌شده سایت</span><strong>{{ money(data.online.paid_sales) }}</strong></article><article><span>میانگین سفارش پرداخت‌شده سایت</span><strong>{{ money(data.online.paid_count ? data.online.paid_sales / data.online.paid_count : 0) }}</strong></article><article><span>مشتری خریدار</span><strong>{{ num(data.online.purchasers) }}</strong></article><article><span>پرداخت‌نشده / لغوشده</span><strong>{{ num(data.online.unpaid_count) }} / {{ num(data.online.canceled_count) }}</strong></article></section>
      <section class="analytics-grid website-grid"><article class="panel"><header><div><h2>روند فروش سایت</h2><p>سفارش‌های ثبت‌شده و پرداخت کامل</p></div></header><StatisticsTrend :sales="data.online.trend" :start="data.period.start" :end="data.period.end" :grouping="data.period.grouping" :show-collections="false" /></article><article class="panel"><header><div><h2>محصولات پرفروش سایت</h2><p>تعداد و مبلغ خط با قیمت تاریخی، پیش از تخفیف</p></div></header><div v-if="data.online.top_products.length" class="bar-list"><div v-for="row in data.online.top_products" :key="row.product_name" class="bar-row"><div><span>{{ row.product_name }}</span><strong>{{ num(row.quantity) }} عدد · {{ money(row.gross) }}</strong></div><div class="track"><i :style="{width:`${Number(row.quantity)/maxProduct*100}%`}"></i></div></div></div><p v-else class="empty">قیمت تاریخی کافی برای نمایش محصول وجود ندارد.</p></article><article class="panel"><header><div><h2>ساعت‌های سفارش سایت</h2><p>زمان تهران · همه سفارش‌های ثبت‌شده</p></div></header><div v-if="data.online.hours.length" class="hour-bars"><div v-for="row in data.online.hours" :key="row.hour"><i :style="{height:`${Math.max(5,row.count/maxHour*100)}%`}"><title>{{ num(row.hour) }}:۰۰ · {{ num(row.count) }} سفارش</title></i><small>{{ num(row.hour) }}</small></div></div><p v-else class="empty">سفارشی برای نمایش وجود ندارد.</p></article><article class="panel"><header><div><h2>پرداخت‌های سایت</h2><p>دریافت موفق در بازه، بر اساس روش واقعی پرداخت</p></div></header><div v-for="row in data.online.payments" :key="row.kind" class="panel-foot"><span>{{ methodLabels[row.kind] || 'سایر' }}</span><strong>{{ money(row.amount) }}</strong></div><p v-if="!data.online.payments.length" class="empty">پرداختی در این بازه وجود ندارد.</p></article></section>

      <section class="panel"><header><div><h2>تعداد سفارش‌های سایت در گذر زمان</h2><p>بر اساس تاریخ ثبت؛ همه وضعیت‌های سفارش سایت</p></div></header><div v-if="data.online.order_trend.length" class="bar-list period-list"><div v-for="row in data.online.order_trend" :key="row.period" class="bar-row"><div><span>{{ date(row.period) }}</span><strong>{{ num(row.count) }} سفارش</strong></div><div class="track"><i :style="{width:`${Number(row.count)/maxOnlineOrders*100}%`}"></i></div></div></div><p v-else class="empty">سفارشی در این بازه ثبت نشده است.</p></section>
      <section class="section-heading"><div><span class="eyebrow">کیف پول و تسویه</span><h2>آمار کیف پول و پرداخت بعدی</h2><p>شارژ کیف پول فروش محصول محسوب نمی‌شود.</p></div></section>
      <section class="mini-kpis wallet-grid"><article><span>شارژ موفق</span><strong>{{ money(data.wallet.topup_amount) }}</strong><small>{{ data.wallet.topup_count == null ? 'دسترسی کامل لازم است' : `${num(data.wallet.topup_count)} شارژ · میانگین ${money(data.wallet.topup_count ? data.wallet.topup_amount / data.wallet.topup_count : 0)}` }}</small></article><article><span>خرید با کیف پول</span><strong>{{ money(data.wallet.spending) }}</strong><small>{{ num(data.wallet.funded_orders) }} سفارش</small></article><article><span>عودت به کیف پول</span><strong>{{ money(data.wallet.refunds) }}</strong><small>فقط عودت موفق ثبت‌شده</small></article><article><span>موجودی کیف پول‌ها</span><strong>{{ money(data.wallet.balance) }}</strong><small>مانده فعلی، نه فروش</small></article><article><span>دریافت بعدی در بازه</span><strong>{{ money(data.settlement.amount) }}</strong><small>{{ num(data.settlement.count) }} تسویه ثبت‌شده</small></article></section>
      <section class="panel"><header><div><h2>سن مانده سفارش‌ها</h2><p>فقط سفارش‌های پرداخت‌نشده ثبت‌شده در بازه، بر اساس سن تا اکنون</p></div></header><div class="status-grid"><div v-for="row in data.settlement.outstanding_age" :key="row.label"><span>{{ row.label }}</span><strong>{{ money(row.amount) }}</strong></div></div></section>
      <section class="panel limitations"><div><h2>هزینه‌ها و سود عملیاتی</h2><p>{{ data.expenses.reason }} هزینه خرید مواد و سربار ممکن است در بهای تولید نیز آمده باشند؛ سود خالص یا عملیاتی برآورد نمی‌شود.</p></div><span>اطلاعات کافی نیست</span></section>
      <p class="definitions">{{ data.definitions.filters }} بازه سفارش و بازه وصول متفاوت‌اند؛ پرداخت‌های لغوشده در وصول موفق کنونی لحاظ نمی‌شوند.</p>
    </template>
  </main>
</template>

<style scoped>
.period-list{max-height:300px;overflow-y:auto;padding-inline-end:4px}
.statistics{--stat-accent:#9a623a;display:grid;gap:18px;max-width:1600px;margin:auto;padding:8px 4px 40px;color:var(--text)}.hero{display:flex;align-items:end;justify-content:space-between;gap:16px}.hero h1{margin:7px 0 4px;font-size:clamp(1.5rem,2.5vw,2rem);letter-spacing:-.04em}.hero p,.section-heading p{margin:0;color:var(--muted);font-size:.8rem}.eyebrow,.kicker{color:var(--stat-accent);font-size:.67rem;font-weight:800;letter-spacing:.02em}.eyebrow i{display:inline-block;width:5px;height:5px;margin:0 4px;border-radius:50%;background:#4d9b86;vertical-align:middle}.refresh,.apply,.reset,.presets button{font:inherit;cursor:pointer}.refresh{display:flex;align-items:center;gap:7px;padding:9px 14px;border:1px solid var(--border);border-radius:11px;background:var(--surface);color:var(--text);font-size:.75rem;font-weight:700}.refresh span{font-size:1.2rem}.filter-card,.panel,.kpi,.mini-kpis article{background:var(--surface);border:1px solid var(--border);box-shadow:0 8px 28px #3d281408}.filter-card{display:grid;gap:13px;padding:15px 17px;border-radius:16px}.filter-top{display:flex;justify-content:space-between;gap:10px}.filter-top strong,.filter-top small{display:block}.filter-top strong{font-size:.79rem}.filter-top small{margin-top:3px;color:var(--muted);font-size:.68rem}.reset{border:0;background:transparent;color:var(--stat-accent);font-size:.7rem}.presets{display:flex;gap:6px;overflow:auto;scrollbar-width:thin}.presets button{flex:0 0 auto;padding:7px 11px;border:1px solid var(--border);border-radius:9px;background:var(--surface-subtle);color:var(--muted);font-size:.7rem}.presets button.active{border-color:var(--stat-accent);background:color-mix(in srgb,var(--stat-accent) 12%,var(--surface));color:var(--stat-accent);font-weight:800}.filters{display:flex;align-items:end;gap:9px;flex-wrap:wrap}.filters label{display:grid;gap:4px;min-width:130px;flex:1;color:var(--muted);font-size:.67rem}.filters select{min-height:36px;padding:6px 9px;border:1px solid var(--border);border-radius:8px;background:var(--input);color:var(--text);font:inherit}.filters :deep(.jalali-input){min-height:36px}.apply{min-height:36px;padding:7px 15px;border:0;border-radius:8px;background:var(--stat-accent);color:#fff;font-size:.72rem;font-weight:700}.kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px}.kpi{position:relative;min-width:0;display:grid;gap:8px;padding:17px;border-radius:15px;overflow:hidden}.kpi span,.mini-kpis span{color:var(--muted);font-size:.71rem}.kpi strong,.mini-kpis strong{font-size:clamp(.9rem,1.35vw,1.18rem);overflow-wrap:anywhere}.kpi small,.mini-kpis small,.muted{color:var(--muted);font-size:.65rem}.kpi b{position:absolute;left:14px;top:12px;display:grid;place-items:center;width:30px;height:30px;border-radius:10px;background:var(--surface-subtle);color:var(--stat-accent)}.kpi.primary{background:linear-gradient(135deg,#6a3e26,#a96b42);color:#fff;border-color:transparent}.kpi.primary span,.kpi.primary small{color:#f2ded0}.kpi.primary b{background:#ffffff20;color:#fff}.kpi.compact{padding:13px 17px;gap:5px}.unavailable{font-size:.95rem!important;color:var(--muted)}.analytics-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.panel{min-width:0;padding:18px;border-radius:16px}.panel header{display:flex;justify-content:space-between;gap:8px;align-items:start;margin-bottom:14px}.panel h2,.section-heading h2{margin:4px 0;font-size:1rem}.panel header p,.panel header small{margin:0;color:var(--muted);font-size:.68rem;line-height:1.8}.pill{flex-shrink:0;padding:5px 9px;border-radius:999px;background:var(--surface-subtle);color:var(--muted);font-size:.65rem}.notice{margin:12px 0 0;padding:10px 12px;border-radius:9px;background:var(--surface-subtle);color:var(--muted);font-size:.68rem;line-height:1.9}.source-content{display:grid;grid-template-columns:155px minmax(0,1fr);gap:18px;align-items:center;min-height:220px}.donut{width:150px;height:150px;border-radius:50%;display:grid;place-items:center}.donut>di