-size:.58rem;color:var(--muted)}.limitations{display:flex;justify-content:space-between;align-items:center;gap:15px}.limitations p{margin:5px 0 0;color:var(--muted);font-size:.72rem;line-height:1.9}.limitations>span{flex:none;padding:7px 10px;border-radius:999px;background:var(--surface-subtle);color:var(--muted);font-size:.68rem}.definitions{margin:0;color:var(--muted);font-size:.68rem;line-height:2}.empty{color:var(--muted);font-size:.75rem}.error-state{display:grid;justify-items:center;gap:8px;padding:40px;background:var(--surface);border:1px solid var(--border);border-radius:15px;color:var(--color-danger)}.error-state button{padding:8px 15px;border:1px solid var(--border);border-radius:8px;background:var(--surface);color:var(--text);cursor:pointer}.skeleton-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:11px}.skeleton{height:100px;border-radius:15px;background:linear-gradient(90deg,var(--surface-subtle),var(--surface-hover),var(--surface-subtle));background-size:200% 100%;animation:shimmer 1.4s infinite}@keyframes shimmer{to{background-position:-200% 0}}@media(max-width:1100px){.website-grid{grid-template-columns:1fr 1fr}.wallet-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:760px){.kpis,.mini-kpis,.wallet-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.analytics-grid,.website-grid{grid-template-columns:1fr}.source-content{grid-template-columns:140px minmax(0,1fr)}.donut{width:135px;height:135px}.donut>div{width:96px;height:96px}.skeleton-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:420px){.hero{align-items:start}.hero p{max-width:220px}.refresh{padding:7px;font-size:.65rem}.source-content{grid-template-columns:1fr;justify-items:center}.legend{width:100%}.filters label{min-width:110px}.status-grid{grid-template-columns:repeat(2,1fr)}.limitations{align-items:start;flex-direction:column}}
